defmodule Bench do
  def group_runs(list, gap) when is_list(list) do
    sorted = Enum.sort(list)

    {start, last, runs} =
      Enum.reduce(sorted, {nil, nil, []}, fn x, {s, l, rs} ->
        cond do
          is_nil(s) -> {x, x, rs}
          x - l <= gap -> {s, x, rs}
          true -> {x, x, [{s, l} | rs]}
        end
      end)

    if is_nil(start), do: [], else: Enum.reverse([{start, last} | runs])
  end
end
