defmodule Bench.Counter do
  use GenServer

  def start_link(initial) do
    GenServer.start_link(__MODULE__, initial)
  end

  def increment(pid), do: increment(pid, 1)

  def increment(pid, n), do: GenServer.call(pid, {:increment, n})

  def value(pid), do: GenServer.call(pid, :value)

  def reset(pid), do: GenServer.call(pid, :reset)

  @impl true
  def init(initial) do
    {:ok, %{value: initial, initial: initial}}
  end

  @impl true
  def handle_call({:increment, n}, _from, state) do
    {:reply, :ok, %{state | value: state.value + n}}
  end

  def handle_call(:value, _from, state) do
    {:reply, state.value, state}
  end

  def handle_call(:reset, _from, state) do
    {:reply, :ok, %{state | value: state.initial}}
  end
end
